import os
import re
import sys

# NOTE: this script is intended to be called by 05b_STAR_tabulate_uniquely_mapped_reads.sh!

# Filename of final .tsv file containing the uniquely mapped reads as logged in STARLog.final.out files
final_tsv_filename = "../05_STAR_alignments/05b_STAR_unique_mapped_reads.tsv"

# Function to use regex to find the uniquiely mapped reads percentage as logged in STARLog.final.out files generated by STAR.
def find_uniquely_mapped_reads(file_input):
    with open(file_input, 'r') as infile:
        content = infile.read()
        
        #Pulls filename of the log file read to be saved later
        filename = os.path.basename(infile.name)
        uniquely_mapped_reads = re.search(r"Uniquely mapped reads % \|\t(\d{1,3}\.\d{2}%)", content).group(1)
    return filename, uniquely_mapped_reads
    
# Function to write the data scraped in find_uniquely_mapped_reads to a .tsv file declared in final_tsv_filename variable
def write_to_tsv(infile_name, read_percentage):
    with open(final_tsv_filename, 'a') as outfile:
        final_line = infile_name + '\t' + read_percentage + '\n'
        outfile.write(final_line)

if __name__ == "__main__":
    # Automatically takes in [filename] from arguments written in the command line (i.e. python tabulate_uniquely_mapped_reads_05b.py [FILENAME])
    original_filename, mapped_read_percentage = find_uniquely_mapped_reads(sys.argv[1])
    write_to_tsv(original_filename,mapped_read_percentage)